from pathlib import Path
import ast,pprint
p=Path('gui/i18n.py');s=p.read_text(encoding='utf-8');tree=ast.parse(s)
n=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='PT_BR' for t in n.targets));d=ast.literal_eval(n.value)
d.update({'INTERFACE LANGUAGE':'IDIOMA DA INTERFACE','Could not save interface language: {error}':'Não foi possível salvar o idioma da interface: {error}', 'INITIALISING':'INICIALIZANDO','LISTENING':'OUVINDO','SPEAKING':'FALANDO','THINKING':'RACIOCINANDO','PROCESSING':'PROCESSANDO','MUTED':'SILENCIADO','IDLE':'EM ESPERA','READY':'PRONTO','CONNECTING':'CONECTANDO','DISCONNECTED':'DESCONECTADO','WAIT':'AGUARDE','QUEUED':'NA FILA','DONE':'CONCLUÍDO','FAILED':'FALHOU','STOPPED':'INTERROMPIDO','✓  correct':'✓  correto', "…  noted — I'll go over this one with you":'…  anotado — vou analisar esta resposta com você', 'Personal AI Assistant':'Assistente pessoal de IA','MIC · MUTED':'MIC · SILENCIADO','MIC · LIVE':'MIC · ATIVO','ENGINE · {engine}':'MOTOR · {engine}','PROTOCOL · {protocol}':'PROTOCOLO · {protocol}','HEARING':'RECONHECIMENTO','turns what you say into words':'transforma sua fala em palavras','understands, decides, uses your tools':'compreende, decide e usa suas ferramentas','reads the answer out loud':'lê a resposta em voz alta','checking…':'verificando…','reading…':'carregando…','Nothing to check for this one.':'Nada para verificar neste provedor.','Nothing to list for this one.':'Nada para listar neste provedor.','None found.':'Nenhum resultado.', ' and ':' e ', 'VIDEO':'VÍDEO','PICTURE':'IMAGEM','Document':'Documento', 'DEFAULT  (follow system)':'PADRÃO  (seguir o sistema)', 'MICROPHONE':'MICROFONE','SPEAKERS':'ALTO-FALANTES'})
lines=s.splitlines(keepends=True);a=sum(map(len,lines[:n.lineno-1]));b=sum(map(len,lines[:n.end_lineno]));s=s[:a]+'PT_BR = '+pprint.pformat(d,sort_dicts=True,width=100)+'\n'+s[b:];p.write_text(s,encoding='utf-8',newline='\n')
# Preserve newline style and never blanket-translate external text.
def edit(name,fn):
 p=Path(name);s=p.read_bytes().decode('utf-8').replace('\r\n','\n');s=fn(s);ast.parse(s);p.write_bytes(s.replace('\n','\r\n').encode('utf-8'))
edit('gui/widgets.py', lambda s:s.replace('tr, render, QLabel','tr, render, _Localized, QLabel').replace('class IconButton(QWidget):','class IconButton(_Localized, QWidget):').replace('items = [(str(a), str(b)) for a, b in items]','items = [(a, str(b)) for a, b in items]').replace('self._right = str(text or "")','self._right = text or ""').replace('right_w = fm.horizontalAdvance(self._right)','right_w = fm.horizontalAdvance(render(self._right))').replace('w = fm.horizontalAdvance(label)','w = fm.horizontalAdvance(render(label))').replace('state = self._state_text(t)','state = render(tr(self._state_text(t)))'))
edit('gui/window.py',lambda s:s.replace('else "Personal AI Assistant")','else tr("Personal AI Assistant"))').replace('("MIC · MUTED", "MUTED_C")','(tr("MIC · MUTED"), "MUTED_C")').replace('("MIC · LIVE", "GREEN")','(tr("MIC · LIVE"), "GREEN")').replace('f"ENGINE · {getattr(self, \'_engine_label\', \'GEMINI LIVE\')}"','tr("ENGINE · {engine}", engine=getattr(self, "_engine_label", "GEMINI LIVE"))').replace('f"PROTOCOL · {APP_PROTOCOL}"','tr("PROTOCOL · {protocol}", protocol=APP_PROTOCOL)').replace("title[:44] if title else 'VIDEO'", "title[:44] if title else tr('VIDEO')").replace("title[:44] if title else 'PICTURE'", "title[:44] if title else tr('PICTURE')").replace("(title or \"Document\")[:48]", "(title or tr('Document'))[:48]"))
edit('gui/providers_panel.py',lambda s:s.replace('self._label(what,','self._label(tr(what),').replace("v0=name)","v0=tr(name))").replace('self._say(pid, "checking…",','self._say(pid, tr("checking…"),').replace('self._say(pid, "reading…",','self._say(pid, tr("reading…"),').replace('self._say(pid, "Nothing to check for this one.",','self._say(pid, tr("Nothing to check for this one."),').replace('self._say(pid, "Nothing to list for this one.",','self._say(pid, tr("Nothing to list for this one."),').replace('else "None found.",','else tr("None found."),'))
print('Catalog and painted states updated',len(d))